{"cards": [{"node_code": "N_3d3cd2196b2940d7", "definition": "研究面向设备健康管理的数字孪生建模、远程智能运维架构、边缘计算诊断及多源运维数据闭环与群体设备知识学习。", "boundary": "聚焦于利用数字孪生与网络通信技术实现设备状态的远程感知、实时映射与智能决策。包括物理-虚拟映射、边缘-云协同、运维数据闭环及群体设备健康分析。与“状态监测”的区别在于：本节点侧重系统架构、远程交互与数据闭环，而非单一信号处理。与“故障诊断”的区别在于：本节点侧重基于孪生模型的远程运维决策，而非离线或本地诊断算法本身。", "includes": ["设备健康数字孪生建模、虚实交互与同步技术", "远程监控、边缘诊断架构及云边协同运维系统", "运维数据闭环、群体设备健康分析与维修知识沉淀"], "excludes": ["制造过程数字孪生或产品全生命周期数字主线（归入制造工程或PLM相关节点）", "通用的故障检测算法或纯信号处理技术（归入状态监测与特征工程或故障检测与诊断）"], "sibling_distinctions": [{"other_code": "N_93c0620d9c9235fd", "rule": "本节点侧重基于数字孪生的远程系统架构与数据闭环；兄弟节点侧重传感器信号处理、特征提取等底层数据预处理技术。"}, {"other_code": "N_dd1fc4c780863f08", "rule": "本节点侧重利用孪生模型进行远程运维决策与状态映射；兄弟节点侧重具体的故障识别、分类与定位算法。"}, {"other_code": "N_27b438ea77f88184", "rule": "本节点侧重运维系统的架构、远程交互与数据管理；兄弟节点侧重剩余寿命预测模型、健康指标评估及健康管理策略。"}], "cross_boundary_rule": "若研究重点在于构建虚实映射模型或远程运维系统架构，主挂载至本节点；若重点在于具体的故障诊断算法或寿命预测模型，主挂载至“故障检测与诊断”或“预测与健康管理”。"}, {"node_code": "N_342de529877f044d", "definition": "研究机械系统在故障发生后的恢复策略、自修复材料/结构技术、容错控制机制及系统鲁棒性提升方法。", "boundary": "聚焦于故障发生后的“响应-恢复-适应”过程。包括故障隔离、冗余切换、自修复材料/结构、容错控制算法及系统降级运行策略。与“故障诊断”的区别在于：本节点侧重故障后的恢复与容错，而非故障前的检测与识别。与“维护工程”的区别在于：本节点侧重系统层面的自动恢复与容错，而非人工维修作业或备件管理。", "includes": ["故障隔离、冗余切换与容错控制策略", "自修复材料、自修复结构及微胶囊/血管网络技术", "系统鲁棒性设计、降级运行模式及故障后性能恢复"], "excludes": ["故障的检测、识别与诊断算法（归入故障检测与诊断）", "人工维修作业流程、备件库存管理及维护策略优化（归入维护工程与资产管理）"], "sibling_distinctions": [{"other_code": "N_dd1fc4c780863f08", "rule": "本节点侧重故障发生后的恢复、自修复与容错机制；兄弟节点侧重故障发生前的检测、识别与定位。"}, {"other_code": "N_27b438ea77f88184", "rule": "本节点侧重故障后的即时恢复与系统容错；兄弟节点侧重基于健康状态的寿命预测与长期健康管理。"}], "cross_boundary_rule": "若研究重点在于故障后的系统恢复、自修复或容错控制，主挂载至本节点；若重点在于故障的早期检测或寿命预测，主挂载至“故障检测与诊断”或“预测与健康管理”。"}]}
